"""
What Lanvex may do in Lanvex Core through the API: exactly the least-privilege set documented for an
external NetBox (Lanvex docs/operations.md, "NetBox token permissions"), nothing more.
"""
import re
from dataclasses import dataclass

__all__ = ('ROLE_GROUPS', 'SERVICE_PERMISSIONS', 'TOKEN_PATTERN', 'ServicePermission')

# nbt_<12-character key>.<40-character secret>, generated by the Lanvex installer.
TOKEN_PATTERN = re.compile(r'^nbt_(?P<key>[A-Za-z0-9]{12})\.(?P<secret>[A-Za-z0-9]{40})$')

# Lanvex roles, as sent in the group header. Administrators become superusers in Lanvex Core.
ROLE_GROUPS = ('lanvex-admin', 'lanvex-readonly')


@dataclass(frozen=True)
class ServicePermission:
    name: str
    actions: tuple
    object_types: tuple
    description: str


SERVICE_PERMISSIONS = (
    ServicePermission(
        name='Lanvex: networks, addresses and VLANs',
        actions=('view', 'add', 'change', 'delete'),
        object_types=('ipam.prefix', 'ipam.ipaddress', 'ipam.vlan'),
        description='Lanvex creates, edits and deletes these on behalf of its users.',
    ),
    ServicePermission(
        name='Lanvex: interfaces',
        actions=('view', 'change'),
        object_types=('dcim.interface',),
        description='Lanvex only edits 802.1Q mode and VLANs.',
    ),
    ServicePermission(
        name='Lanvex: tags',
        actions=('view', 'add'),
        object_types=('extras.tag',),
        description='Lanvex creates the lanvex-gateway tag once.',
    ),
    ServicePermission(
        name='Lanvex: reference data',
        actions=('view',),
        object_types=(
            'ipam.vrf', 'ipam.role', 'ipam.vlangroup', 'ipam.iprange',
            'dcim.device', 'dcim.site', 'dcim.devicerole', 'dcim.manufacturer',
            'tenancy.tenant', 'core.objectchange', 'virtualization.virtualmachine',
        ),
        description='Read only.',
    ),
)
